CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,student_id VARCHAR(50) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,phone VARCHAR(20) NOT NULL,department VARCHAR(100) NOT NULL,year TINYINT NOT NULL,campus_area VARCHAR(100) NOT NULL,role ENUM('user','admin') NOT NULL DEFAULT 'user',is_active TINYINT NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS categories (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) UNIQUE NOT NULL,icon VARCHAR(30) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS items (id INT AUTO_INCREMENT PRIMARY KEY,owner_id INT NOT NULL,category_id INT NOT NULL,name VARCHAR(80) NOT NULL,description VARCHAR(500) NOT NULL,location VARCHAR(100) NOT NULL,latitude DECIMAL(9,6) NULL,longitude DECIMAL(9,6) NULL,available_from DATE NOT NULL,available_to DATE NOT NULL,status ENUM('active','paused','removed') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_item_owner FOREIGN KEY(owner_id) REFERENCES users(id),CONSTRAINT fk_item_category FOREIGN KEY(category_id) REFERENCES categories(id),CHECK(available_to>=available_from),INDEX(owner_id),INDEX(category_id),INDEX(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS borrow_requests (id INT AUTO_INCREMENT PRIMARY KEY,item_id INT NOT NULL,borrower_id INT NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,message VARCHAR(255),status ENUM('requested','accepted','borrowed','return_pending','completed','rejected','cancelled') DEFAULT 'requested',handover_code CHAR(6),code_expires_at DATETIME,code_attempts TINYINT DEFAULT 0,cancelled_by INT,cancelled_from VARCHAR(20),borrowed_at DATETIME,returned_at DATETIME,completed_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(item_id) REFERENCES items(id),FOREIGN KEY(borrower_id) REFERENCES users(id),FOREIGN KEY(cancelled_by) REFERENCES users(id),INDEX(item_id,status),INDEX(borrower_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS request_events (id INT AUTO_INCREMENT PRIMARY KEY,request_id INT NOT NULL,status VARCHAR(30) NOT NULL,actor_id INT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(request_id) REFERENCES borrow_requests(id) ON DELETE CASCADE,FOREIGN KEY(actor_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS reviews (id INT AUTO_INCREMENT PRIMARY KEY,request_id INT NOT NULL,reviewer_id INT NOT NULL,reviewee_id INT NOT NULL,rating TINYINT NOT NULL,comment VARCHAR(300),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(request_id,reviewer_id),FOREIGN KEY(request_id) REFERENCES borrow_requests(id),FOREIGN KEY(reviewer_id) REFERENCES users(id),FOREIGN KEY(reviewee_id) REFERENCES users(id),CHECK(rating BETWEEN 1 AND 5)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS wishlist (user_id INT NOT NULL,item_id INT NOT NULL,notify TINYINT DEFAULT 0,PRIMARY KEY(user_id,item_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(item_id) REFERENCES items(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS notifications (id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,type VARCHAR(40) NOT NULL,message VARCHAR(255) NOT NULL,request_id INT,item_id INT,is_read TINYINT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(user_id,is_read)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
